fn __d_entry_type(dentry: *const dentry) -> u32 {
(unsafe { (*dentry).d_flags }) & 3670016
}

fn d_is_miss(dentry: *const dentry) -> bool {
__d_entry_type(dentry) == 0
}

fn d_is_negative(dentry: *const dentry) -> bool {
// TODO: check d_is_whiteout(dentry) also.
d_is_miss(dentry)
}

fn d_is_positive(dentry: *const dentry) -> bool {
!d_is_negative(dentry)
}

fn d_backing_inode(upper: *const dentry) -> *mut inode {
let inode: *mut inode = unsafe { (*upper).d_inode };
inode
}

